import csv
import io
import re


def render_group_csv(groups: list[dict]) -> dict[str, str]:
    if not isinstance(groups, list):
        raise TypeError("groups must be a list")
    result = {}
    for group in groups:
        if not isinstance(group, dict) or set(group) != {"name", "enabled", "rows"}:
            raise ValueError("malformed group")
        name = group["name"]
        enabled = group["enabled"]
        rows = group["rows"]
        if not isinstance(name, str) or not name.strip():
            raise ValueError("name must be a non-empty string")
        if not isinstance(enabled, bool):
            raise TypeError("enabled must be a bool")
        if not isinstance(rows, list):
            raise TypeError("rows must be a list")
        checked = []
        for row in rows:
            if not isinstance(row, (list, tuple)) or len(row) != 4:
                raise ValueError("each row must contain four fields")
            if not all(isinstance(value, str) for value in row):
                raise TypeError("row fields must be strings")
            checked.append(tuple(row))
        if not enabled:
            continue
        stem = re.sub(r"\s+", "_", name.strip()).strip("_").lower()
        filename = (stem or "group") + ".csv"
        if filename in result:
            raise ValueError("duplicate output filename")
        stream = io.StringIO(newline="")
        writer = csv.writer(stream, lineterminator="\n")
        writer.writerow(["Item", "Units", "Unit Cost", "Zone"])
        writer.writerows(checked)
        result[filename] = stream.getvalue()
    return result

